class Node:
    def __init__(self, val=0, left=None, right=None):
        self.val, self.left, self.right = val, left, right

def solve(root):
    # Skeleton for: Construct Binary Tree from inorder and preorder
    def dfs(node):
        if not node:
            return 0  # adapt base
        left = dfs(node.left)
        right = dfs(node.right)
        return 1 + max(left, right)  # adapt combine
    return dfs(root)
